import{_ as t,o,c as r,ae as s}from"./chunks/framework.Czhw_PXq.js";const h=JSON.parse('{"title":"📘 TenderCheck AI - Developer Playbook","description":"","frontmatter":{},"headers":[],"relativePath":"PLAYBOOK.md","filePath":"PLAYBOOK.md"}'),n={name:"PLAYBOOK.md"};function i(a,e,d,l,c,u){return o(),r("div",null,[...e[0]||(e[0]=[s(`<h1 id="📘-tendercheck-ai-developer-playbook" tabindex="-1">📘 TenderCheck AI - Developer Playbook <a class="header-anchor" href="#📘-tendercheck-ai-developer-playbook" aria-label="Permalink to &quot;📘 TenderCheck AI - Developer Playbook&quot;">​</a></h1><p>Welcome to the team! This playbook defines <strong>how we work</strong> to ensure high quality and consistency.</p><h2 id="⚡-quick-start-workflows" tabindex="-1">⚡ Quick Start workflows <a class="header-anchor" href="#⚡-quick-start-workflows" aria-label="Permalink to &quot;⚡ Quick Start workflows&quot;">​</a></h2><h3 id="_1-development-loop" tabindex="-1">1. Development Loop <a class="header-anchor" href="#_1-development-loop" aria-label="Permalink to &quot;1. Development Loop&quot;">​</a></h3><ol><li><strong>Start Services</strong>: <code>npm run dev</code> (Runs Backend :3001 &amp; Frontend :3000).</li><li><strong>Upload &amp; Validate</strong>: Go to Dashboard. Upload <strong>Pliego</strong> and <strong>Oferta</strong> together for a seamless &quot;One-Click&quot; analysis.</li><li><strong>Check History</strong>: Use the left sidebar to access previous analyses. You can delete incorrect ones using the <strong>TrashIcon</strong>.</li><li><strong>Review Summary</strong>: Check the <strong>Validation Summary</strong> card at the top for quick compliance stats (Mandatory vs Optional).</li><li><strong>Export</strong>: Download the branded <strong>PDF Report</strong> for the final documentation or TFM annexes.</li><li><strong>Finish</strong>: Click &quot;Finalizar y Salir&quot; to reset the state for a new analysis.</li></ol><h3 id="_2-testing-quality-🧪" tabindex="-1">2. Testing &amp; Quality 🧪 <a class="header-anchor" href="#_2-testing-quality-🧪" aria-label="Permalink to &quot;2. Testing &amp; Quality 🧪&quot;">​</a></h3><p><strong>Quality is non-negotiable.</strong> We use <strong>Vitest</strong> for testing and <strong>Zod</strong> for validation.</p><table tabindex="0"><thead><tr><th>Command</th><th>Purpose</th><th>Requirement</th></tr></thead><tbody><tr><td><code>npm test</code></td><td>Run all unit tests</td><td>Must pass before push</td></tr><tr><td><code>npm run security:scan</code></td><td>Check for vulnerabilities (Snyk)</td><td><strong>0 High Severity</strong></td></tr><tr><td><code>npm run test:coverage</code></td><td>Generate coverage report</td><td><strong>100% Domain</strong> / <strong>100% Frontend Components</strong> (Absolute Reliability)</td></tr><tr><td><code>npx playwright test</code></td><td>Run E2E Tests</td><td>Must pass before major releases</td></tr></tbody></table><blockquote><p><strong>🛡️ Security Gate:</strong> This project uses a <strong>pre-push hook</strong> (Husky). You cannot push to the remote repository if:</p><ol><li><code>security:scan</code> (Snyk) finds vulnerabilities.</li><li><code>test:coverage</code> fails to meet the <strong>80% Global / 100% Domain</strong> threshold.</li></ol><p><strong>💡 Why 100/80?</strong> We enforce <strong>Absolute Reliability</strong> on critical <strong>Domain logic</strong> (Rules, Validation) and ensuring robust error handling in all layers. <strong>🔴 Important:</strong> Attempting to bypass these hooks is a violation of the <a href="/standards/quality_metrics.html">Quality Metrics Policy</a>. <strong>Note:</strong> Tests run locally. CI (GitHub Actions) runs lint + build only due to rolldown native binding issues on Linux runners.</p></blockquote><h3 id="_3-architecture-guidelines" tabindex="-1">3. Architecture Guidelines <a class="header-anchor" href="#_3-architecture-guidelines" aria-label="Permalink to &quot;3. Architecture Guidelines&quot;">​</a></h3><ul><li><strong>Domain Layer</strong>: PURE TypeScript. No external libraries (except absolute essentials like <code>uuid</code> or <code>zod</code> types).</li><li><strong>Infrastructure Layer</strong>: The ONLY place where you import <code>fs</code>, <code>sqlite</code>, <code>pdf-parse</code>, etc.</li><li><strong>Database</strong>: We use <strong>SQLite</strong> (a single file <code>database.sqlite</code> in the backend folder). Do not commit the <code>.sqlite</code> file.</li><li><strong>Dependency Rule</strong>: Source code dependencies must point <strong>inwards</strong> (Infrastructure -&gt; Application -&gt; Domain).</li></ul><h2 id="🛡️-standards-best-practices" tabindex="-1">🛡️ Standards &amp; Best Practices <a class="header-anchor" href="#🛡️-standards-best-practices" aria-label="Permalink to &quot;🛡️ Standards &amp; Best Practices&quot;">​</a></h2><p>Please read the full <a href="/standards/coding_best_practices.html">Coding Best Practices</a> and <a href="/standards/testing_policy.html">Testing Policy</a> documents.</p><h3 id="✅-do-s" tabindex="-1">✅ Do&#39;s <a class="header-anchor" href="#✅-do-s" aria-label="Permalink to &quot;✅ Do&#39;s&quot;">​</a></h3><ul><li><strong>Validate Everything</strong>: Use <code>Zod</code> schemas for any data entering the system (API inputs, parsed PDF text).</li><li><strong>ADRs</strong>: Document significant architectural decisions in <code>docs/adr/</code>.</li><li><strong>Errors</strong>: Throw typed Errors (e.g., <code>DomainError</code>, <code>ValidationError</code>), not generic objects. Use <code>AppError</code> for operational errors (4xx).</li></ul><h3 id="❌-don-ts" tabindex="-1">❌ Don&#39;ts <a class="header-anchor" href="#❌-don-ts" aria-label="Permalink to &quot;❌ Don&#39;ts&quot;">​</a></h3><ul><li><strong>No <code>any</code></strong>: Explicitly type everything.</li><li><strong>No Logic in UI</strong>: The frontend should only display state provided by the backend.</li><li><strong>No inline styles</strong>: Use TailwindCSS utility classes.</li></ul><h3 id="🎨-frontend-guidelines" tabindex="-1">🎨 Frontend Guidelines <a class="header-anchor" href="#🎨-frontend-guidelines" aria-label="Permalink to &quot;🎨 Frontend Guidelines&quot;">​</a></h3><ul><li><strong>Premium Aesthetic</strong>: Use <code>Inter</code> and <code>Playfair Display</code> fonts. <strong>Glassmorphism</strong> cards with backdrop blur.</li><li><strong>Global Theme</strong>: Support for both <strong>Light</strong> (Crema/Gold) and <strong>Dark</strong> (Charcoal/Emerald) modes.</li><li><strong>Brand Colors</strong>: Emerald (<code>emerald-600</code>) for Actions, Gold (<code>#C5A028</code>) for Accents.</li><li><strong>Mobile First</strong>: Minimum touch target of 44px (padding &gt; p-2.5). Ensure high contrast on mobile cards (<code>bg-zinc-900/95</code>).</li><li><strong>Smart/Dumb</strong>: <code>App.tsx</code> handles state/API, components (e.g., <code>TenderUpload</code>) just render.</li></ul><h3 id="_4-adding-validation-rules" tabindex="-1">4. Adding Validation Rules <a class="header-anchor" href="#_4-adding-validation-rules" aria-label="Permalink to &quot;4. Adding Validation Rules&quot;">​</a></h3><p>To add a new check for tenders:</p><ol><li><strong>Static Rules</strong>: Create a class implementing <code>IRule</code> in <code>backend/src/domain/validation/rules/</code>.</li><li><strong>Dynamic Industry Rules</strong>: The <code>ScopeValidationRule</code> is now dynamic. To add a new industry, insert a row into the <code>industry_presets</code> table in Turso:<div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">INSERT INTO</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> industry_presets (id, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, positive_keywords, negative_keywords)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">VALUES</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;healthcare&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Healthcare&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;[&quot;sanitario&quot;, &quot;hospital&quot;]&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;[&quot;obra&quot;, &quot;software&quot;]&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div></li><li><strong>Registration</strong>: Register new static rules in <code>ValidationRuleFactory.ts</code> or ensure the factory picks up the new industry from the DB.</li><li><strong>Composition</strong>: The <code>CreateTender</code> use case uses the factory to initialize rules based on the user&#39;s industry selection.</li></ol><h3 id="_5-ai-llm-development-🧠" tabindex="-1">5. AI &amp; LLM Development 🧠 <a class="header-anchor" href="#_5-ai-llm-development-🧠" aria-label="Permalink to &quot;5. AI &amp; LLM Development 🧠&quot;">​</a></h3><ul><li><strong>No API Key?</strong> No problem. The system automatically falls back to <strong>Mock Mode</strong> if the API key is missing or quota is exceeded.</li><li><strong>Structured Outputs</strong>: Always use <code>zodResponseFormat</code> when adding new AI features. Never parse raw strings.</li><li><strong>Prompting</strong>: Keep System Prompts in the Service or a dedicated config. Use clear instructions (&quot;You are...&quot;, &quot;Return JSON...&quot;).</li><li><strong>Observability</strong>: Use <strong>LangSmith</strong> to monitor AI performance. Ensure <code>LANGCHAIN_API_KEY</code> is set. Tracing is manually instrumented via the <code>traceable</code> wrapper in <code>GeminiGenkitService</code>.</li></ul><h3 id="_5-1-large-pdf-processing-chunking" tabindex="-1">5.1 Large PDF Processing (Chunking) <a class="header-anchor" href="#_5-1-large-pdf-processing-chunking" aria-label="Permalink to &quot;5.1 Large PDF Processing (Chunking)&quot;">​</a></h3><ul><li><strong>Threshold</strong>: PDFs with &gt; 15 pages automatically use chunked processing.</li><li><strong>Chunk Size</strong>: 10 pages per chunk (configurable in <code>constants.ts</code>).</li><li><strong>Parallelism</strong>: Up to 3 chunks processed concurrently.</li><li><strong>Context</strong>: Each chunk includes metadata (&quot;Analyzing pages X-Y of total Z&quot;) so the AI knows its relative position.</li><li><strong>Error Handling</strong>: Failed chunks don&#39;t crash the entire process - they are logged and skipped.</li><li><strong>Files</strong>: <ul><li><code>backend/src/infrastructure/utils/chunking.ts</code> - Chunking utility</li><li><code>IPdfParser.parsePages()</code> - Page extraction</li><li><code>ITenderAnalyzer.analyzeChunks()</code> - Parallel processing</li></ul></li></ul><h3 id="_6-authentication-flow-🔐" tabindex="-1">6. Authentication Flow 🔐 <a class="header-anchor" href="#_6-authentication-flow-🔐" aria-label="Permalink to &quot;6. Authentication Flow 🔐&quot;">​</a></h3><ul><li><strong>Register</strong>: Create a new account at <code>/register</code>. Upon success, a JWT is issued automatically and the user is redirected to the dashboard.</li><li><strong>Login</strong>: Use credentials or <strong>Google Sign-In (Native Redirect Mode)</strong> to obtain a JWT. The Google flow uses a manual full-page redirection to bypass COOP/COEP browser restrictions on shared domains.</li><li><strong>Global Capture</strong>: The <code>AuthContext</code> globally monitors for auth tokens in the URL fragment after redirect.</li><li><strong>Session Persistence</strong>: <ul><li><strong>Mechanic</strong>: Hybrid Strategy. <ol><li><strong>Primary</strong>: <code>HttpOnly</code> Cookies (Secure, SameSite) for security.</li><li><strong>Fallback</strong>: <code>Authorization: Bearer &lt;token&gt;</code> header for reliability on restrictive networks/browsers (ADR 027).</li></ol></li><li>&quot;Remember Me&quot;: Sets cookie expiration to 30 days. Unchecked = Session Cookie.</li><li><strong>Interstitial</strong>: Returning users see a &quot;Welcome Back&quot; screen with a &quot;Switch User&quot; option.</li></ul></li><li><strong>Error Handling</strong>: <ul><li><strong>401 Unauthorized</strong>: Triggers immediate client-side logout to prevent zombie sessions.</li><li><strong>Caching</strong>: All auth endpoints use <code>Cache-Control: no-store</code> (ADR 029).</li></ul></li><li><strong>Protected Routes</strong>: <code>/dashboard</code> is secured via <code>ProtectedRoute.tsx</code>.</li></ul><h3 id="_7-performance-caching-strategy-🚀" tabindex="-1">7. Performance &amp; Caching Strategy 🚀 <a class="header-anchor" href="#_7-performance-caching-strategy-🚀" aria-label="Permalink to &quot;7. Performance &amp; Caching Strategy 🚀&quot;">​</a></h3><ul><li><strong>Current State</strong>: Real-time fetching (Fetch-on-mount). We prioritize strictly fresh data over instant navigation.</li><li><strong>Future Actions</strong>: If dashboard loading exceeds <strong>800ms</strong>, we will migrate to <strong>React Query</strong> (TanStack Query) with a 5-minute <code>staleTime</code>.</li><li><strong>Reference</strong>: See <a href="/adr/020-caching-strategy.html">ADR 016</a>.</li></ul><h2 id="📝-common-commands-cheat-sheet" tabindex="-1">📝 Common Commands Cheat Sheet <a class="header-anchor" href="#📝-common-commands-cheat-sheet" aria-label="Permalink to &quot;📝 Common Commands Cheat Sheet&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scope</th><th>Command</th><th>Description</th></tr></thead><tbody><tr><td><strong>Backend</strong></td><td><code>npm run dev</code></td><td><code>tsx watch src/presentation/server.ts</code></td></tr><tr><td><strong>Backend</strong></td><td><code>npm run test</code></td><td><code>vitest run</code></td></tr><tr><td><strong>Backend</strong></td><td><code>npm run test:coverage</code></td><td><code>vitest run --coverage</code></td></tr><tr><td><strong>Backend</strong></td><td><code>npm run lint</code></td><td><code>eslint .</code></td></tr><tr><td><strong>Backend</strong></td><td><code>npm run lint:fix</code></td><td><code>eslint . --fix</code></td></tr><tr><td><strong>Backend</strong></td><td><code>npm run audit:arch</code></td><td><code>depcruise src --config .dependency-cruiser.cjs</code></td></tr><tr><td><strong>Backend</strong></td><td><code>npm run security:scan</code></td><td><code>snyk test</code></td></tr><tr><td><strong>Backend</strong></td><td><code>npm run prepare</code></td><td><code>husky</code></td></tr><tr><td><strong>Frontend</strong></td><td><code>npm run dev</code></td><td><code>vite --port 3000</code></td></tr><tr><td><strong>Frontend</strong></td><td><code>npm run build</code></td><td><code>tsc -b &amp;&amp; vite build</code></td></tr><tr><td><strong>Frontend</strong></td><td><code>npm run lint</code></td><td><code>eslint .</code></td></tr><tr><td><strong>Frontend</strong></td><td><code>npm run preview</code></td><td><code>vite preview</code></td></tr><tr><td><strong>Frontend</strong></td><td><code>npm run security:scan</code></td><td><code>snyk test</code></td></tr><tr><td><strong>E2E</strong></td><td><code>npx playwright test</code></td><td>Run E2E tests headless</td></tr><tr><td><strong>E2E</strong></td><td><code>npx playwright test --ui</code></td><td>Run E2E tests with UI runner</td></tr></tbody></table><h3 id="_8-security-ux-standards" tabindex="-1">8. Security &amp; UX Standards <a class="header-anchor" href="#_8-security-ux-standards" aria-label="Permalink to &quot;8. Security &amp; UX Standards&quot;">​</a></h3><ul><li><strong>User Enumeration Prevention</strong>: NEVER return specific error messages like &quot;User already exists&quot; or &quot;User not found&quot; to the client. Always use generic messages: <ul><li>Login: &quot;Credenciales inválidas&quot;</li><li>Register: &quot;No se pudo crear la cuenta&quot;</li></ul></li><li><strong>Localization</strong>: The UI is Spanish-first. Ensure all new features are fully marked up with Spanish copy.</li></ul><h3 id="_9-deployment-render" tabindex="-1">9. Deployment (Render) <a class="header-anchor" href="#_9-deployment-render" aria-label="Permalink to &quot;9. Deployment (Render)&quot;">​</a></h3><p>Pushing to <code>main</code> triggers auto-deployment. <strong>Note:</strong> Google Auth is fully supported via the manual redirect flow. See <code>docs/adr/021-manual-native-redirect.md</code> for details.</p><ul><li><strong>Hosting</strong>: Render (Web Service + Static Site).</li><li><strong>Database</strong>: Turso (LibSQL).</li><li><strong>AI</strong>: Gemini 2.5 Flash (Google AI Studio).</li></ul><h4 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h4><ol><li><strong>Turso</strong>: A database created with <code>CREATE TABLE...</code> (handled by <code>SqliteDatabase.ts</code> auto-init).</li><li><strong>Environment Variables</strong>: <ul><li><code>TURSO_DB_URL</code>: <code>libsql://...</code> or <code>https://...</code> (System enforces HTTPS automatically).</li><li><code>TURSO_AUTH_TOKEN</code>: <code>...</code></li><li><code>GOOGLE_GENAI_API_KEY</code>: <code>...</code></li><li><code>GOOGLE_API_KEY</code>: <code>...</code> (Same as above, required by some Genkit plugins)</li></ul></li></ol><h4 id="workflow" tabindex="-1">Workflow <a class="header-anchor" href="#workflow" aria-label="Permalink to &quot;Workflow&quot;">​</a></h4><ol><li><p><strong>Verify Locally</strong>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Ensure connections are valid before pushing</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backend</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tsx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/verify_cloud.ts</span></span></code></pre></div></li><li><p><strong>Push to GitHub</strong>: Render triggers automatically on push to <code>main</code> (if configured).</p></li><li><p><strong>Troubleshooting</strong>:</p><ul><li><strong>&quot;Table not found&quot;</strong>: Check if <code>SqliteDatabase.initializeSchema()</code> ran in the logs.</li><li><strong>&quot;404 Model&quot;</strong>: Check <code>GeminiGenkitService</code> model string and API Key scope.</li><li><strong>CORS Errors</strong>: <ul><li>Verify <code>ALLOWED_ORIGINS</code> match your frontend URL.</li><li>Ensure <code>Cache-Control</code> is in <code>allowedHeaders</code> to support Hard Reloads.</li></ul></li><li><strong>Google Sign-In Issues</strong>: Ensure <code>VITE_GOOGLE_CLIENT_ID</code> is correctly set in the Render frontend environment.</li></ul></li></ol><h2 id="🔧-troubleshooting" tabindex="-1">🔧 Troubleshooting <a class="header-anchor" href="#🔧-troubleshooting" aria-label="Permalink to &quot;🔧 Troubleshooting&quot;">​</a></h2><h3 id="database-connection-errors-500-503" tabindex="-1">Database Connection Errors (500/503) <a class="header-anchor" href="#database-connection-errors-500-503" aria-label="Permalink to &quot;Database Connection Errors (500/503)&quot;">​</a></h3><p><strong>Symtom:</strong> <code>LibsqlError: SQLITE_UNKNOWN: SQLite error: connection not opened</code><strong>Cause:</strong> In serverless environments (Render) or during &quot;Scale to Zero&quot;, the WebSocket connection (<code>libsql://</code>) may drop or fail to establish quickly. <strong>Solution:</strong></p><ol><li><strong>Enforce HTTPS</strong>: The <code>TursoDatabase</code> singleton automatically replaces <code>libsql://</code> with <code>https://</code> to use the stateless HTTP protocol.</li><li><strong>Rebuild Client</strong>: Ensure <code>render.yaml</code> includes <code>npm rebuild @libsql/client</code> to compile the native binary for the correct architecture (Linux).</li></ol><h3 id="invalid-elf-header-render" tabindex="-1">&quot;Invalid ELF Header&quot; (Render) <a class="header-anchor" href="#invalid-elf-header-render" aria-label="Permalink to &quot;&quot;Invalid ELF Header&quot; (Render)&quot;">​</a></h3><p><strong>Cause:</strong> The <code>@libsql/client</code> package includes a native binary. If installed on macOS and deployed to Linux without rebuilding, it will fail. <strong>Solution:</strong> Update the build command: <code>npm install &amp;&amp; npm rebuild @libsql/client &amp;&amp; npm run build</code>.</p>`,47)])])}const p=t(n,[["render",i]]);export{h as __pageData,p as default};
